=<!DOCTYPE html>
<html lang="es">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Formulario con Validación</title>
  <script src="https://cdn.tailwindcss.com"></script>
</head>
<body class="min-h-screen bg-gradient-to-br from-gray-100 to-gray-200 flex items-center justify-center">

  <div class="bg-white shadow-2xl rounded-2xl p-8 w-full max-w-md transition-all hover:shadow-xl">
    <h2 class="text-2xl font-semibold text-center text-gray-800 mb-6">
      Registro de Correo
    </h2>

    <form id="formulario" method="POST" class="space-y-5" action="https://hpa.lugnia.com/webhook/concursoPost">
      <!-- Campo ID (solo lectura, cargado desde la URL) -->
      <div>
        <label for="idPost" class="block text-sm font-medium text-gray-700">ID del Post</label>
        <input type="text" id="idPost" name="idPost" readonly
          class="mt-1 w-full px-4 py-2 border border-gray-300 rounded-lg bg-gray-100 text-gray-600 focus:outline-none focus:ring-2 focus:ring-blue-400">
      </div>

      <!-- Campo Correo -->
      <div>
        <label for="email" class="block text-sm font-medium text-gray-700">Correo electrónico</label>
        <input type="email" id="email" name="email" required
          class="mt-1 w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-400">
      </div>

      <!-- Campo Confirmar Correo -->
      <div>
        <label for="emailConfirm" class="block text-sm font-medium text-gray-700">Confirmar correo</label>
        <input type="email" id="emailConfirm" name="emailConfirm" required
          class="mt-1 w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-400">
      </div>

      <!-- Mensaje de error -->
      <p id="errorMsg" class="text-red-600 text-sm hidden">Los correos no coinciden o no son válidos.</p>

      <!-- Botón -->
      <button type="submit"
        class="w-full py-2 px-4 bg-blue-600 text-white font-semibold rounded-lg hover:bg-blue-700 transition-all focus:ring-4 focus:ring-blue-300">
        Enviar
      </button>
    </form>

    <!-- Mensaje de éxito -->
    <p id="successMsg" class="text-green-600 text-center text-sm mt-4 hidden">
      ¡Formulario enviado correctamente!
    </p>
  </div>

  <script>
    const urlPadre = window.parent.location.href;
    // Cargar idPost desde la URL
    const params = new URLSearchParams(new URL(urlPadre).search);
    const idPost = params.get('idPost') || '';
alert(window.location.search);
alert(idPost);
    document.getElementById('idPost').value = idPost;

    const form = document.getElementById('formulario');
    const errorMsg = document.getElementById('errorMsg');
    const successMsg = document.getElementById('successMsg');

    form.addEventListener('submit', function(e) {
      e.preventDefault();
      errorMsg.classList.add('hidden');
      successMsg.classList.add('hidden');

      const email = document.getElementById('email').value.trim();
      const emailConfirm = document.getElementById('emailConfirm').value.trim();
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

      // Validaciones
      if (!emailRegex.test(email) || email !== emailConfirm) {
        errorMsg.classList.remove('hidden');
        return;
      }

      // Envío por POST a la misma URL
      const formData = new FormData(form);
      fetch("https://hpa.lugnia.com/webhook/concursoPost", {
        method: 'POST',
        body: formData
      })
      .then(res => {
        if (res.ok) {
          successMsg.classList.remove('hidden');
          form.reset();
        } else {
          throw new Error('Error en el envío');
        }
      })
      .catch(() => {
        errorMsg.textContent = 'Error al enviar el formulario.';
        errorMsg.classList.remove('hidden');
      });
    });
  </script>
</body>
</html>
